#!/usr/bin/env node
/**
 * Assemble worklet entry.mjs / web-entry.mjs from concat parts.
 * Parts are the editable source; the assembled files are build inputs.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const workletRoot = join(dirname(fileURLToPath(import.meta.url)), "../worklet");

const ENTRY_PARTS = [
  "entry-part-1.mjs",
  "entry-part-2.mjs",
  "entry-part-3.mjs",
];
const WEB_ENTRY_PARTS = ["web-entry-part-1.mjs", "web-entry-part-2.mjs"];

const BANNER =
  "/* Generated by scripts/assemble-worklet-entries.mjs — edit entry-part-*.mjs / web-entry-part-*.mjs instead. */\n";

function assemble(parts, outName) {
  const chunks = parts.map((name, index) => {
    let text = readFileSync(join(workletRoot, name), "utf8");
    if (index > 0 && text.startsWith("/* Concat part")) {
      text = text.slice(text.indexOf("\n") + 1);
    }
    return text;
  });
  writeFileSync(join(workletRoot, outName), BANNER + chunks.join(""));
}

assemble(ENTRY_PARTS, "entry.mjs");
assemble(WEB_ENTRY_PARTS, "web-entry.mjs");
console.log("assembled worklet entry.mjs and web-entry.mjs from parts");
